// Module: Currencies · route /currency · 5 form field(s), 5 required (from Validators.*)
// Requires TARGET_APP_URL, APP_TEST_USERNAME, APP_TEST_PASSWORD (auth.setup fast path supported).
import { test, expect } from '@playwright/test';
import { ensureCapboSession, fillAngularField, selectMatDropdown, searchList } from './helpers/capbo-ui';

// Serial: View/Edit/Delete operate on the record Create makes.
test.describe.configure({ mode: 'serial' });

test.describe("Currencies CRUD", () => {
  test.setTimeout(45_000);
  const suffix = Date.now().toString(36).slice(-5);
  const name = `e2e-currency-${suffix}`;
  const updatedName = `${name}-upd`;

  test('Create Currencies with all required fields', async ({ page }) => {
    await ensureCapboSession(page, "/currency");
    await page.getByTestId("currency-create").click({ timeout: 15000 });

    // currency.currencyCode — autocomplete (code)
    await fillAngularField(page, page.getByTestId("currency-code"), "NQA");
    // currency.numericCode — mat-input (numericCode)
    await fillAngularField(page, page.getByTestId("currency-numeric-code"), "228");
    // currency.nameOfCurrency — mat-input (name)
    await fillAngularField(page, page.getByTestId("currency-name"), name);
    // currency.symbol — mat-input (symbol)
    await fillAngularField(page, page.getByTestId("currency-symbol"), "symbol-jhc9w");
    // currency.rounding — mat-input (roundingIncrement)
    await fillAngularField(page, page.getByTestId("currency-rounding-increment"), "0.01");

    const save = page.getByTestId("currency-save");
    await expect(save, 'save must enable once required controls are valid').toBeEnabled({ timeout: 8000 });
    await save.click({ timeout: 15000 });

    await searchList(page, name, {"testId":"currency-search","control":null,"route":"/currency"});
    await expect(page.locator("[data-testid=\"currency-row\"], table tbody tr, .mat-mdc-row, .mat-row").filter({ hasText: name }).first()).toBeVisible({ timeout: 15000 });
  });

  test('View created Currencies', async ({ page }) => {
    await ensureCapboSession(page, "/currency");
    await searchList(page, name, {"testId":"currency-search","control":null,"route":"/currency"});
    await page.locator("[data-testid=\"currency-row\"], table tbody tr, .mat-mdc-row, .mat-row").filter({ hasText: name }).first().getByTestId("currency-view").or(page.getByTestId("currency-view").first()).first().click({ timeout: 10000 });
    await expect(page.getByTestId("currency-name")).toHaveValue(name, { timeout: 10000 });
  });

  test('Edit Currencies (name)', async ({ page }) => {
    await ensureCapboSession(page, "/currency");
    await searchList(page, name, {"testId":"currency-search","control":null,"route":"/currency"});
    await page.locator("[data-testid=\"currency-row\"], table tbody tr, .mat-mdc-row, .mat-row").filter({ hasText: name }).first().getByTestId("currency-edit").or(page.getByTestId("currency-edit").first()).first().click({ timeout: 10000 });
    await fillAngularField(page, page.getByTestId("currency-name"), updatedName);
    await page.getByTestId("currency-save").click({ timeout: 15000 });
    await searchList(page, updatedName, {"testId":"currency-search","control":null,"route":"/currency"});
    await expect(page.locator("[data-testid=\"currency-row\"], table tbody tr, .mat-mdc-row, .mat-row").filter({ hasText: updatedName }).first()).toBeVisible({ timeout: 15000 });
  });

  test('Validation: required fields gate the save button', async ({ page }) => {
    await ensureCapboSession(page, "/currency");
    await page.getByTestId("currency-create").click({ timeout: 15000 });
    // 5 required control(s) from Validators.required → empty form must not be savable
    await expect(page.getByTestId("currency-save")).toBeDisabled({ timeout: 8000 });
    // Touch + clear the name field → required error must appear
    await fillAngularField(page, page.getByTestId("currency-name"), 'x');
    await fillAngularField(page, page.getByTestId("currency-name"), '');
    await page.keyboard.press('Tab');
    await expect(page.locator('mat-error').first()).toBeVisible({ timeout: 5000 });
    await page.getByTestId("currency-cancel").click({ timeout: 8000 }).catch(() => {});
  });

  test('Delete Currencies', async ({ page }) => {
    await ensureCapboSession(page, "/currency");
    await searchList(page, updatedName, {"testId":"currency-search","control":null,"route":"/currency"});
    await page.locator("[data-testid=\"currency-row\"], table tbody tr, .mat-mdc-row, .mat-row").filter({ hasText: updatedName }).first().getByTestId("currency-edit").or(page.getByTestId("currency-edit").first()).first().click({ timeout: 10000 });
    await page.getByTestId("currency-delete").click({ timeout: 10000 });
    // Confirm dialog (testid from shared confirmation component)
    await page.getByTestId("confirm").click({ timeout: 8000 });
    await searchList(page, updatedName, {"testId":"currency-search","control":null,"route":"/currency"});
    await expect(page.locator("[data-testid=\"currency-row\"], table tbody tr, .mat-mdc-row, .mat-row").filter({ hasText: updatedName }).first()).toBeHidden({ timeout: 15000 });
  });

});
